541	  }
542	  current[segments[segments.length - 1]] = value;
543	  return true;
544	}
545	
546	function processFormField(spec, input, nodeId) {
547	  const error = code => ({ nodeId, path: spec.path, code });
548	  const { exists, value } = lookupOwn(input, spec.segments);
549	
550	  if (!exists) {
551	    if (spec.hasDefault) {
552	      if (!isUsableObject(input) || !applyDefault(input, spec.segments, spec.default)) {
553	        return error('type');
554	      }
555	      return null;
556	    }
557	    return spec.required ? error('required') : null;
558	  }
559	
560	  if (!valueMatchesType(value, spec.type)) return error('type');
561	  if (!valueSatisfiesBounds(value, spec)) {
562	    return error(spec.type === 'string' ? 'length' : 'range');
563	  }
564	  return null;
565	}
566	
567	function processForm(node, input, compiled) {
568	  const snapshot = structuredClone(input);
569	  const errors = [];
570	  for (const spec of compiled) {
571	    const fieldError = processFormField(spec, input, node.id);
572	    if (fieldError) errors.push(fieldError);
573	  }
574	  return errors.length === 0
575	    ? { ok: true }
576	    : { ok: false, errors, rollback: snapshot };
577	}
578	
579	// Wait before a retry. Timers are the only suspension point: no other node is
580	// ever scheduled while an action waits.
581	function sleep(ms) {
582	  return new Promise(resolve => setTimeout(resolve, ms));
583	}
584	
585	function describeError(error) {
586	  if (error instanceof Error) return error.message;
587	  return String(error);
588	}
589	
590	// Delay before the attempt following the given (failed) attempt number: the
591	// initial wait grows by the backoff factor each time and is capped by the
592	// configured maximum. A zero initial delay always stays zero.
593	function retryDelay(retry, failedAttempt) {
594	  const grown = retry.initialDelayMs * (retry.backoffFactor ** (failedAttempt - 1));
595	  return Math.min(grown, retry.maxDelayMs);
596	}
597	
598	// Runs one business action with retries. Every invocation receives fresh
599	// structured clones of the current input and the successful outputs so far;
600	// mutations by a failed attempt are discarded, and the stored success value
601	// is a clone independent of any object the implementation keeps holding.
602	async function runBusinessAction(node, binding, implementation, context, actionAttempts) {
603	  const { retry } = binding;
604	  let lastReason = null;
605	
606	  for (let attempt = 1; attempt <= retry.attempts; attempt += 1) {
607	    const inputCopy = structuredClone(context.input);
608	    const outputCopy = structuredClone(context.output);
609	    const record = { nodeId: node.id, attempt, ok: false, error: null, nextDelayMs: 0 };
610	    let returned;
611	    try {
612	      returned = await implementation(inputCopy, outputCopy, node.id, attempt);
613	    } catch (error) {
614	      lastReason = describeError(error);
615	      record.error = lastReason;
616	    }
617	
618	    if (record.error === null) {
619	      try {
620	        returned = structuredClone(returned);
621	      } catch (error) {
622	        lastReason = `operation "${binding.name}" returned a value that cannot be structured-cloned`;
623	        record.error = lastReason;
624	      }
625	    }
626	
627	    if (record.error === null) {
628	      record.ok = true;
629	      actionAttempts.push(record);
630	      return { ok: true, value: returned };
631	    }
632	
633	    record.nextDelayMs = attempt < retry.attempts ? retryDelay(retry, attempt) : 0;
634	    actionAttempts.push(record);
635	    if (record.nextDelayMs > 0) await sleep(record.nextDelayMs);
636	  }
637	
638	  return { ok: false, error: lastReason };
639	}
640	
641	// Scheduling state shared by the synchronous and asynchronous execution
642	// loops: activation, completion, dependency gating and the recorded end
643	// result all behave identically; only business-action handling differs.
644	function createRunState(nodes, workflow, input) {
645	  const declarationOrder = [...nodes.values()];
646	  const declarationIndex = new Map(declarationOrder.map((node, index) => [node.id, index]));
647	  return {
648	    trace: [],
649	    actionAttempts: [],
650	    context: { input: structuredClone(input), output: {} },
651	    declarationOrder,
652	    declarationIndex,
653	    activated: new Set([workflow.entry]),
654	    completed: new Set(),
655	    endReached: false,
656	    endResult: null,
657	  };
658	}
659	
660	function pickReadyNode(state) {
661	  return state.declarationOrder.find(node =>
662	    state.activated.has(node.id) && !state.completed.has(node.id)
663	    && nodeDependencies.get(node).every(dependency => state.completed.has(dependency)));
664	}
665	
666	function blockedResult(state) {
667	  const waiting = state.declarationOrder.filter(node =>
668	    state.activated.has(node.id) && !state.completed.has(node.id));
669	  if (waiting.length === 0) return null;
670	  return waiting.map(node => ({
671	    nodeId: node.id,
672	    missingDependencies: nodeDependencies.get(node)
673	      .filter(dependency => !state.completed.has(dependency))
674	      .sort((a, b) => state.declarationIndex.get(a) - state.declarationIndex.get(b)),
675	  }));
676	}
677	
678	// Applies a ready non-action node, mutating activation/completion state.
679	// Returns an early-termination result (invalid_input / invalid_condition)
680	// or null when execution should continue.
681	function applyRegularNode(node, state) {
682	  if (node.type === 'action') {
683	    state.context.output[node.id] = node.message ?? `action:${node.id}`;
684	  }
685	  if (node.type === 'form') {
686	    const compiled = formSchemas.get(node);
687	    if (compiled) {
688	      const formResult = processForm(node, state.context.input, compiled);
689	      if (!formResult.ok) {
690	        state.context.input = formResult.rollback;
691	        return { status: 'invalid_input', context: state.context, trace: state.trace, errors: formResult.errors };
692	      }
693	    }
694	  }
695	  if (node.type === 'condition') {
696	    const outcome = runCondition(compiledConditions.get(node), state.context.input, node.id);
697	    if (!outcome.ok) {
698	      return { status: 'invalid_condition', context: state.context, trace: state.trace, error: outcome.error };
699	    }
700	    state.activated.add(outcome.value ? node.then : node.else);
701	  } else {
702	    for (const target of successorTargets.get(node)) state.activated.add(target);
703	  }
704	  state.completed.add(node.id);
705	  return null;
706	}
707	
708	// Verifies, before a single node can run, that every business action in the
709	// definition has a function registered — including actions on untaken
710	// branches and entry-unreachable nodes.
711	function verifyOperations(nodes, operations) {
712	  for (const node of nodes.values()) {
713	    const binding = actionBindings.get(node);
714	    if (binding && binding.name !== null) {
715	      if (!isUsableObject(operations)
716	        || !Object.hasOwn(operations, binding.name)
717	        || typeof operations[binding.name] !== 'function') {
718	        throw new Error(`action node ${node.id}: operation "${binding.name}" has no function implementation; pass it to executeWorkflowAsync`);
719	      }
720	    }
721	  }
722	}
723	
724	export function executeWorkflow(workflow, input = {}) {
725	  const nodes = validateWorkflow(workflow);
726	  // Business operations are asynchronous: the synchronous entry must refuse
727	  // a workflow that names any before a single node executes.
728	  for (const node of nodes.values()) {
729	    const binding = actionBindings.get(node);
730	    if (binding && binding.name !== null) {
731	      throw new Error(`action node ${node.id} names business operation "${binding.name}", which must run asynchronously; use executeWorkflowAsync instead of executeWorkflow`);
732	    }
733	  }
734	
735	  const state = createRunState(nodes, workflow, input);
736	
737	  for (;;) {
738	    const ready = pickReadyNode(state);
739	
740	    if (!ready) {
741	      const blockedNodes = blockedResult(state);
742	      if (blockedNodes) {
743	        return { status: 'blocked', context: state.context, trace: state.trace, blockedNodes };
744	      }
745	      if (state.endReached) {
746	        return { status: 'completed', result: state.endResult, context: state.context, trace: state.trace };
747	      }
748	      throw new Error('workflow did not terminate; a cycle is present');
749	    }
750	
751	    state.trace.push({ nodeId: ready.id, type: ready.type });
752	    if (ready.type === 'end') {
753	      // Reaching an end node records the result but never stops other
754	      // activated branches; the run completes once nothing can still run.
755	      state.endReached = true;
756	      state.endResult = ready.result ?? null;
757	      state.completed.add(ready.id);
758	      continue;
759	    }
760	
761	    const early = applyRegularNode(ready, state);
762	    if (early) return early;
763	  }
764	}
765	
766	export async function executeWorkflowAsync(workflow, input = {}, operations = {}) {
767	  const nodes = validateWorkflow(workflow);
768	  verifyOperations(nodes, operations);
769	
770	  const state = createRunState(nodes, workflow, input);
771	
772	  for (;;) {
773	    const ready = pickReadyNode(state);
774	
775	    if (!ready) {
776	      const blockedNodes = blockedResult(state);
777	      if (blockedNodes) {
778	        return {
779	          status: 'blocked', context: state.context, trace: state.trace,
780	          blockedNodes, actionAttempts: state.actionAttempts,
781	        };
782	      }
783	      if (state.endReached) {
784	        return {
785	          status: 'completed', result: state.endResult, context: state.context,
786	          trace: state.trace, actionAttempts: state.actionAttempts,
787	        };
788	      }
789	      throw new Error('workflow did not terminate; a cycle is present');
790	    }
791	
792	    state.trace.push({ nodeId: ready.id, type: ready.type });
793	    if (ready.type === 'end') {
794	      state.endReached = true;
795	      state.endResult = ready.result ?? null;
796	      state.completed.add(ready.id);
797	      continue;
798	    }
799	
800	    if (ready.type === 'action') {
801	      const binding = actionBindings.get(ready);
802	      if (binding.name !== null) {
803	        // Nodes execute one at a time in declaration order; awaiting here
804	        // never lets another node jump ahead.
805	        const actionResult = await runBusinessAction(
806	          ready, binding, operations[binding.name], state.context, state.actionAttempts);
807	        if (!actionResult.ok) {
808	          // Retries are exhausted: stop immediately with prior input/output
809	          // preserved, no output for this node and no successors activated —
810	          // even if an end node was already reached.
811	          return {
812	            status: 'action_failed', nodeId: ready.id, attempts: binding.retry.attempts,
813	            error: actionResult.error, context: state.context, trace: state.trace,
814	            actionAttempts: state.actionAttempts,
815	          };
816	        }
817	        state.context.output[ready.id] = actionResult.value;
818	        for (const target of successorTargets.get(ready)) state.activated.add(target);
819	        state.completed.add(ready.id);
820	        continue;
821	      }
822	    }
823	
824	    const early = applyRegularNode(ready, state);
825	    if (early) {
826	      early.actionAttempts = state.actionAttempts;
827	      return early;
828	    }
829	  }
830	}
