    [{ compensation: { operation: 'comp', retry: null } }, /compensation\.retry must be an object/],
    [{ compensation: { operation: 'comp', retry: {} } }, /compensation\.retry must define all of/],
    [{ compensation: { operation: 'comp', retry: { attempts: 0, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 } } }, /compensation\.retry\.attempts/],
    [{ compensation: { operation: 'comp', retry: { attempts: 11, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 } } }, /compensation\.retry\.attempts/],
