test('rejects malformed compensation definitions before execution', () => {
  const badDefinitions = [
    [{ compensation: null }, /compensation must be an object/],
    [{ compensation: 'nope' }, /compensation must be an object/],
    [{ compensation: {} }, /compensation\.operation must be a non-empty string/],
    [{ compensation: { operation: '' } }, /compensation\.operation must be a non-empty string/],
    [{ compensation: { operation: '   ' } }, /compensation\.operation must be a non-empty string/],
    [{ compensation: { operation: 7 } }, /compensation\.operation must be a non-empty string/],
    [{ compensation: { operation: 'comp', retry: null } }, /compensation\.retry must be an object/],
    [{ compensation: { operation: 'comp', retry: {} } }, /compensation\.retry must define all of/],
    [{ compensation: { operation: 'comp', retry: { attempts: 0, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 } } }, /compensation\.retry\.attempts/],
    [{ compensation: { operation: 'comp', retry: { attempts: 11, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 } } }, /compensation\.retry\.attempts/],
    [{ compensation: { operation: 'comp', retry: { attempts: 1, initialDelayMs: -1, backoffFactor: 1, maxDelayMs: 0 } } }, /compensation\.retry\.initialDelayMs/],
    [{ compensation: { operation: 'comp', retry: { attempts: 1, initialDelayMs: 60001, backoffFactor: 1, maxDelayMs: 60001 } } }, /compensation\.retry\.initialDelayMs/],
    [{ compensation: { operation: 'comp', retry: { attempts: 1, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: -1 } } }, /compensation\.retry\.maxDelayMs/],
    [{ compensation: { operation: 'comp', retry: { attempts: 1, initialDelayMs: 0, backoffFactor: 4.5, maxDelayMs: 0 } } }, /compensation\.retry\.backoffFactor/],
    [{ compensation: { operation: 'comp', retry: { attempts: 1, initialDelayMs: 10, backoffFactor: 1, maxDelayMs: 5 } } }, /compensation\.retry\.maxDelayMs must not be less than/],
  ];
  for (const [actionProps, matcher] of badDefinitions) {
    const workflow = linearWorkflow(actionProps);
    assert.throws(() => validateWorkflow(workflow), matcher);
  }
});

